// Calculate Quote — Run Once for Each Item
const rates      = $('Read rates').all().map(i => i.json);
const zones      = $('Read zones').all().map(i => i.json);
const surcharges = $('Read surcharges').all().map(i => i.json);

const e = $json;
const o = e.output ?? {};
const link = 'https://example.com/book (TEST LINK)';
const WAY_MULT = { 1: 1, 2: 1.8, 3: 2.5 };   // from FAQ-10
const TIER_LABEL = { '1_day': 'same-day', '3_hours': '3-hour express', '90_min': '90-minute express', '60_min': '60-minute express' };

const norm = s => String(s ?? '').trim().toLowerCase();
const zoneOf = area => zones.find(z => norm(z.area) === norm(area))?.zone ?? null;

// Price for one service tier, or null if we can't serve it
function priceFor(tier, weight, fromZone, toZone, ways) {
  const bike = rates.find(r => norm(r.vehicle) === 'bike' && norm(r.service_tier) === tier);
  const van  = rates.find(r => norm(r.vehicle) === 'van'  && norm(r.service_tier) === tier);
  const rate = [bike, van].find(r => r && weight <= Number(r.max_kg));
  const sur  = surcharges.find(s => norm(s.from_zone) === norm(fromZone) && norm(s.to_zone) === norm(toZone));
  if (!rate || !sur) return null;
  const extraKg = Math.max(0, Math.ceil(weight - Number(rate.included_kg)));
  const oneWay  = Number(rate.base_price_sgd) + Number(sur.surcharge_sgd) + extraKg * Number(rate.extra_per_kg_sgd);
  return {
    vehicle: norm(rate.vehicle),
    priceSgd: Math.round(oneWay * WAY_MULT[ways] * 100) / 100,
    bookDayAhead: String(rate.book_day_ahead).toUpperCase() === 'TRUE',
  };
}

// 1. Unknown area? We can't quote regardless of other details.
const fromZone = o.pickupArea  ? zoneOf(o.pickupArea)  : null;
const toZone   = o.dropoffArea ? zoneOf(o.dropoffArea) : null;
const unknownArea = (o.pickupArea && !fromZone) || (o.dropoffArea && !toZone);

// 2. Missing details?
const missing = [];
if (!o.pickupArea)  missing.push('pickup location');
if (!o.dropoffArea) missing.push('drop-off location');
if (o.weightKg === undefined || o.weightKg === null || o.weightKg === '') missing.push('approximate weight');

let quote, replyBrief;

if (unknownArea) {
  quote = { status: 'cannot_quote', reason: 'location not in our zone list' };
} else if (missing.length) {
  quote = { status: 'missing_info', missing };
  replyBrief = `We can quote as soon as we have: ${missing.join(', ')}. Ask the customer for these details. Do not guess or give any price.`;
} else {
  const weight = Number(o.weightKg);
  const ways   = WAY_MULT[Number(o.ways)] ? Number(o.ways) : 1;
  const tier   = TIER_LABEL[o.serviceTier] ? o.serviceTier : '1_day';
  const main   = priceFor(tier, weight, fromZone, toZone, ways);

  if (!main) {
    quote = { status: 'cannot_quote', reason: 'weight or service outside our standard rates' };
  } else {
    const sgt = DateTime.fromISO(e.receivedAt).setZone('Asia/Singapore');
    const afterCutoff = tier === '1_day' && ((sgt.weekday <= 5 && sgt.hour >= 11) || sgt.weekday === 7);

    quote = { status: 'quoted', tier, ways, fromZone, toZone, weightKg: weight, ...main, afterCutoff };

    const lines = [
      `Price: SGD ${main.priceSgd.toFixed(2)} for ${TIER_LABEL[tier]} ${main.vehicle} delivery from ${o.pickupArea} to ${o.dropoffArea}, ${weight} kg${ways > 1 ? `, ${ways}-way` : ''}.`,
    ];
    if (main.bookDayAhead) lines.push('Van deliveries must be booked one day in advance.');
    if (afterCutoff) {
      lines.push('This request came in after our 11:00 AM same-day cut-off, so same-day service would be scheduled for the next business day.');
      const express = priceFor('3_hours', weight, fromZone, toZone, ways);
      if (express) lines.push(`If they need it today, our 3-hour express is SGD ${express.priceSgd.toFixed(2)}.`);
    }
    lines.push(`Book through ${link}. Confirmation takes 10–15 minutes.`);
    lines.push('State the price exactly as written. Do not add discounts, promises or other prices.');
    replyBrief = lines.join('\n');
  }
}

// Shared brief for every "cannot quote" case
if (quote.status === 'cannot_quote') {
  replyBrief = `We cannot give an instant quote for this request (${quote.reason}). Say our team will reply with a quote today. This is the whole message: do not add any other notes, prices or promises.`;
}

return { json: { ...e, quote, replyBrief } };
